pub fn is_palindrome(s: &str) -> bool {
    let mut left = 0;
    let mut right = s.chars().count() - 1;
    while left < right {
        let current_char = if let Some(c) = s.chars().nth(left) {
            c.is_alphabetic() || c.is_digit(10)
        } else {
            '\0'
        } {
            c
        }?;
        let other_char = if let Some(c) = s.chars().nth(right) {
            c.is_alphabetic() || c.is_digit(10)
        } else {
            '\0'
        } {
            c
        }?;
        if current_char != other_char {
            return false;
        }
        left += 1;
        right -= 1;
    }
    true
}

