pub fn rle(input: &str) -> String {
    let mut out = String::new();
    let mut left = input.chars();
    while let Some(first) = left.next() {
        let mut count = 1;
        while let Some(next) = left.next() {
            if first == next {
                count += 1;
            } else {
                break;
            }
        }
        out.push_str(&format!("{:d}", count));
        left = left.chars().take(count).collect();
    }
    out
}

