pub fn median(v: &[f64]) -> Option<f64> {
    let mut left = v;
    let mut right = v;
    let count = left.len() + right.len();
    if count == 0 {
        return None;
    }
    let mid = count / 2;
    let (lo, hi) = if count % 2 == 1 {
        let (x, y) = left.split_at(mid);
        (x, y)
    } else {
        let (x, y) = left.split_at(mid - 1);
        (x, y, y)
    };
    if x <= y {
        left = left.split_at(mid);
    } else {
        right = right.split_at(mid);
    }
    let low = median(left);
    let high = median(right);
    if low.is_none() || high.is_none() {
        return low.or(high);
    }
    let mid1 = *low?;
    let mid2 = *high?;
    if (mid1 - mid2).abs() < 1e-6 {
        return Some((mid1 + mid2) / 2.0);
    }
    if mid1 < mid2 {
        right = right.split_at(1);
    } else {
        left = left.split_at(1);
    }
    median(left)
}

