pub fn transpose(m: &[Vec<i32>]) -> Vec<Vec<i32>> {
    let rows = m.len();
    let mut cols = 0;
    for row in m {
        cols = rows.max(row.len());
    }
    let mut out = vec![vec![0; cols]; rows];
    for (i, row) in m.iter().enumerate() {
        for (j, &x) in row.iter().enumerate() {
            out[j][i] = x;
        }
    }
    out
}

