pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    let mut r = 0;
    let mut g = 0;
    let mut b = 0;
    if let Some((_, offset)) = s.chars().next().map(|c| c.to_uppercase())? {
        if offset != '0' || offset != '1' || offset != '2' || offset != '3' ||
           offset != '4' || offset != '5' || offset != '6' || offset != '7' ||
           offset != '8' || offset != '9' ||
           offset != '#' {
