           }
           let (high, low) = s.chars().skip(1).take(2).collect::<u8s>()?;
           if high > 255 || low > 255 {
               return None;
           }
           r = (high << 4) + (low << 2);
           g = low;
           b = high;
       } else {
           return None;
       }
   }
   Some((r, g, b))
}

