    let (width, height) = *SIZE.lock().unwrap();
    let mut pixels = PIXELS.lock().unwrap();
    for y in 0..height {
        for x in 0..width {
            let i = (y * width + x) * 4;
            let shade = if x < width / 2 { 0 } else { 255 };
            pixels[i] = shade;
            pixels[i + 1] = shade;
            pixels[i + 2] = shade;
            pixels[i + 3] = 255;
        }
    }
    pixels.as_ptr()
}

